def GetObject(objectname):
    val = _gmat_py.GetObject(objectname)

    typestr = val.GetTypeName()
    if (typestr == "ForceModel"):
       typestr = "ODEModel"

    evalstr = typestr + ".SetClass(val)"
    try:
       val = eval(evalstr)
    except:
       pass


    return val

def Construct(*args):
