    typestr = val.GetTypeName()
    if (typestr == "ForceModel"):
       typestr = "ODEModel"

    evalstr = typestr + ".SetClass(val)"
    try:
       val = eval(evalstr)
    except:
       pass

    val.thisown = 0


    return val

